"""Rebuild download data after changing a file in files/ or docs/."""
import base64
import json
from pathlib import Path

root = Path(__file__).resolve().parent
payloads = {}
for folder in ('files', 'docs'):
    for file in sorted((root / folder).iterdir()):
        if file.is_file():
            payloads[file.relative_to(root).as_posix()] = base64.b64encode(file.read_bytes()).decode('ascii')
(root / 'downloads.js').write_text(
    '// Generated by prepare_downloads.py; keep the original files alongside this bundle.\n'
    + 'window.WORKSHOP_DOWNLOADS = Object.freeze('
    + json.dumps(payloads, separators=(',', ':'))
    + ');\n', encoding='utf-8'
)
print(f'Bundled {len(payloads)} downloadable files.')
